input.new_string:
    pairs = []
    for key, value in params.items():
        if value is None:
            continue
        values = value if isinstance(value, (list, tuple)) else [value]
        for item in values:
            pairs.append(_encode(key) + "=" + _encode(item))
    return "&".join(pairs)


def _encode(value) -> str:
    if value is True:
        text = "true"
    elif value is False:
        text = "false"
    else:
        text = str(value)
    # quote() leaves only ASCII letters, digits and "-._~" unescaped when
    # safe="", and encodes a space as %20 (unlike quote_plus, which uses "+").
    return quote(text, safe="", encoding="utf-8")
